  mode: "vim",
  name: "input() returns `null` when &lt;Esc&gt; is pressed",
  fn: async (denops) =&gt; {
    await autocmd.group(denops, "denops_std_helper_input", (helper) =&gt; {
      helper.remove("*");
      helper.define(
        "CmdlineEnter",
        "*",
        `call feedkeys("Hello world!\\&lt;Esc&gt;", "t")`,
      );
    });
    const result = await input(denops);
    assertEquals(result, null);
  },
});```

